//! Generated Unicode tables (XID, `White_Space`) used by the lexer and name resolution.
//!
//! Status: stub (Phase 1). The tables are generated by `cargo xtask gen-unicode` from the
//! Unicode Character Database 17.0.0 (ADR 0018 §1).

/// The name of this crate, used by the driver for diagnostics about the pipeline.
pub const CRATE_NAME: &str = "loom_unicode";

#[cfg(test)]
mod tests {
    use super::CRATE_NAME;

    #[test]
    fn crate_name_matches_package() {
        assert_eq!(CRATE_NAME, env!("CARGO_PKG_NAME"));
    }
}
